import { requireAdmin } from "./auth.js";
import { getNode, bulkPatchRoot } from "./repository.js";
import { escapeHtml, toast } from "./utils.js";

const root=document.getElementById("bootstrapContent");
function count(obj){return obj&&typeof obj==="object"?Object.keys(obj).length:0;}
async function init(){const session=await requireAdmin();const seed=await fetch("../seed/master-data.json").then(r=>r.json());const existing=await getNode("students");const hasExisting=count(existing)>0;root.className="panel";root.innerHTML=`<div class="panel-head"><h3>Baseline Siap Diimpor</h3><span class="badge ${hasExisting?"gold":""}">${hasExisting?"Firebase sudah berisi santri":"Firebase belum berisi santri"}</span></div><div class="portal-metrics compact">${card("Santri",count(seed.students))}${card("SDM",count(seed.staff))}${card("Kelas",count(seed.classes))}${card("Kamar",count(seed.rooms))}${card("Halaqah",count(seed.groups))}${card("Jadwal Akademik",count(seed.schedules?.academic))}</div><div class="notice ${hasExisting?"":"info"}" style="margin:18px 0">${hasExisting?`Ditemukan ${count(existing)} santri di Firebase. Bootstrap otomatis dinonaktifkan agar tidak menimpa data yang sudah ada.`:`Import akan mengisi master data, penempatan Exact, jadwal yang tersedia, isu validasi, dan konfigurasi awal keuangan. Data kandidat/fuzzy tetap masuk ke seed_validation dan tidak dijadikan assignment final.`}</div><button id="seedBtn" class="btn btn-primary" ${hasExisting?"disabled":""}>Import Master Data Sekarang</button><p class="muted" style="font-size:11px;margin-top:12px">Sumber: ${escapeHtml(seed.metadata?.sourceWorkbook||"")}</p>`;document.getElementById("seedBtn")?.addEventListener("click",async()=>{if(!confirm("Import baseline ke Firebase MadaniApp?"))return;const btn=document.getElementById("seedBtn");btn.disabled=true;btn.textContent="Mengimpor…";try{const changes={};for(const [k,v] of Object.entries(seed)){if(k==="metadata")continue;changes[k]=v;}await bulkPatchRoot(changes,session.user.uid,"bootstrap_master_data");toast("Master data berhasil diimpor.");btn.textContent="Selesai";}catch(err){console.error(err);toast(err.message||"Import gagal","error");btn.disabled=false;btn.textContent="Coba Lagi";}});}
function card(label,value){return `<div class="portal-metric blue"><span>${escapeHtml(label)}</span><strong>${escapeHtml(value)}</strong></div>`;}
init().catch(err=>{root.className="empty-state error-state";root.innerHTML=`<strong>Gagal membuka bootstrap</strong><p>${escapeHtml(err.message||String(err))}</p>`;});
